<?php
declare(strict_types=1);

function mr_number(mixed $v):float {return is_numeric($v)&&is_finite((float)$v)?(float)$v:0.0;}
function mr_operational(array $r):bool {return empty($r['managedReconciliation'])&&empty($r['managementOnly'])&&!( !empty($r['systemFixed'])&&!empty($r['noStockPost']));}
function mr_input_rows(array $run):array {
    $out=[];foreach((array)($run['rawInputs']??[]) as $r){if(!is_array($r))continue;$gross=mr_number($r['grossKg']??0);$less=mr_number($r['lessKg']??0);if($gross<=0||$less<0||$less>$gross)continue;$out[]=['lotRef'=>(string)($r['lotRef']??''),'product'=>(string)($r['product']??$run['variety']??''),'bags'=>mr_number($r['bags']??0),'grossKg'=>$gross,'lessKg'=>$less,'kg'=>round($gross-$less,3),'brand'=>(string)($r['brand']??$run['recoveryBrand']??''),'contractRef'=>(string)($r['contractRef']??$run['recoveryContractRef']??'')];}
    if(!$out&&mr_number($run['actualInputKg']??0)>0)$out[]=['lotRef'=>(string)($run['rawLotRef']??''),'product'=>(string)($run['variety']??''),'bags'=>0,'grossKg'=>mr_number($run['actualInputKg']),'lessKg'=>0,'kg'=>mr_number($run['actualInputKg']),'brand'=>(string)($run['recoveryBrand']??''),'contractRef'=>(string)($run['recoveryContractRef']??'')];
    return $out;
}
function mr_actual_input(array $run):?float {$rows=mr_input_rows($run);return $rows?round(array_sum(array_column($rows,'kg')),3):null;}
function mr_output_rows(array $run):array {
    $out=[];foreach((array)($run['rows']??[]) as $r){if(!is_array($r)||!mr_operational($r))continue;$gross=mr_number($r['systemKg']??0);if($gross<=0)$gross=mr_number($r['bags']??0)*mr_number($r['bagWeight']??0)+mr_number($r['loadingAdjustmentKg']??0);$less=mr_number($r['lessKg']??0);$kg=round($gross-$less,3);if($kg<=0)continue;$name=(string)($r['product']??'Unknown');$finished=str_starts_with(strtoupper($name),'READY RICE');$context=(array)($run['recoveryOutputContexts'][(string)($r['id']??'')]??[]);$brand=(string)($context['brand']??$r['brand']??($finished?preg_replace('/^Ready Rice\s*[—-]\s*/iu','',$name):($run['recoveryBrand']??'')));$contract=(string)($context['contractRef']??$r['contractRef']??$run['recoveryContractRef']??'');$out[]=['product'=>$name,'bags'=>mr_number($r['bags']??0),'grossKg'=>$gross,'lessKg'=>$less,'kg'=>$kg,'kind'=>$finished?'finished':'byproduct','brand'=>$brand,'contractRef'=>$contract,'lotRef'=>(string)($r['lotRef']??$run['outputLotRef']??'')];}return $out;
}
function mr_validate_inputs(array $run):void {
    foreach((array)($run['rawInputs']??[]) as $r){if(!is_array($r)||mr_number($r['grossKg']??0)<=0||mr_number($r['lessKg']??0)<0||mr_number($r['lessKg']??0)>=mr_number($r['grossKg']??0))throw new DomainException('Each raw input needs its actual gross kilograms and a valid deduction.');}
    if(!empty($run['recoveryVersion'])&&mr_output_rows($run)&&!(mr_actual_input($run)>0))throw new DomainException('Actual raw input kilograms are required for a production recovery report.');
}
function mr_report(array $runs,array $filters=[],array $accounts=[]):array {
    $entity=(string)($filters['entity']??'TTI');$mode=(string)($filters['mode']??'daily');$groups=[];$brands=[];$contracts=[];$missing=[];
    foreach($runs as $run){if(!is_array($run)||strtoupper((string)($run['entity']??'TTI'))!==$entity)continue;$date=(string)($run['date']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))continue;$inputs=mr_input_rows($run);$outputs=mr_output_rows($run);foreach(array_merge($inputs,$outputs) as $r){if($r['brand']!=='')$brands[$r['brand']]=true;if($r['contractRef']!=='')$contracts[$r['contractRef']]=true;}
        if((!empty($filters['from'])&&$date<$filters['from'])||(!empty($filters['to'])&&$date>$filters['to'])||(!empty($filters['shift'])&&($run['shift']??'')!==$filters['shift'])||(!empty($filters['variety'])&&($run['variety']??'')!==$filters['variety'])||(!empty($filters['mill'])&&($run['millName']??$run['locationName']??'TTI Rice Mills')!==$filters['mill']))continue;
        $id=(string)($run['id']??$date.'|'.($run['shift']??''));if(!$inputs)$missing[$id]=true;
        foreach(['raw'=>$inputs,'output'=>$outputs] as $kind=>$rows)foreach($rows as $row){if((!empty($filters['brand'])&&$row['brand']!==$filters['brand'])||(!empty($filters['contract'])&&$row['contractRef']!==$filters['contract']))continue;$key=$mode==='brand'?($row['brand']?:'Unassigned brand'):($mode==='contract'?($row['contractRef']?:'Unassigned contract'):$date);if(!isset($groups[$key]))$groups[$key]=['key'=>$key,'inputKg'=>0.0,'readyKg'=>0.0,'byProductKg'=>0.0,'outputKg'=>0.0,'inputComplete'=>true,'raw'=>[],'finished'=>[],'byproducts'=>[],'runs'=>[],'costRates'=>[],'inputByRun'=>[],'outputByRun'=>[]];$g=&$groups[$key];$g['runs'][$id]=['id'=>$id,'date'=>$date,'shift'=>(string)($run['shift']??''),'variety'=>(string)($run['variety']??''),'mill'=>(string)($run['millName']??$run['locationName']??'TTI Rice Mills'),'varianceReason'=>(string)($run['recoveryVarianceReason']??'')];if(!$inputs)$g['inputComplete']=false;$row+=['date'=>$date,'shift'=>(string)($run['shift']??''),'sourceRunId'=>$id];if($kind==='raw'){$g['inputKg']+=$row['kg'];$g['inputByRun'][$id]=($g['inputByRun'][$id]??0)+$row['kg'];$g['raw'][]=$row;}else{$g['outputKg']+=$row['kg'];$g['outputByRun'][$id]=true;if($row['kind']==='finished'){$g['readyKg']+=$row['kg'];$g['finished'][]=$row;}else{$g['byProductKg']+=$row['kg'];$g['byproducts'][]=$row;}}unset($g);}
    }
    ksort($groups);$totals=['inputKg'=>0.,'readyKg'=>0.,'byProductKg'=>0.,'outputKg'=>0.,'inputComplete'=>true];
    foreach($groups as &$g){foreach(['inputKg','readyKg','byProductKg','outputKg'] as $k){$g[$k]=round($g[$k],3);$totals[$k]+=$g[$k];}foreach($g['outputByRun'] as $runId=>$unused)if(($g['inputByRun'][$runId]??0)<=0)$g['inputComplete']=false;unset($g['inputByRun'],$g['outputByRun']);if($g['inputKg']<=0&&$g['outputKg']>0)$g['inputComplete']=false;$g['inputComplete']=$g['inputComplete']&&$g['raw']!==[];$totals['inputComplete']=$totals['inputComplete']&&$g['inputComplete'];$g['recoveryPct']=$g['inputComplete']&&$g['inputKg']>0?round($g['outputKg']/$g['inputKg']*100,4):null;$g['readyRecoveryPct']=$g['inputComplete']&&$g['inputKg']>0?round($g['readyKg']/$g['inputKg']*100,4):null;$g['differenceKg']=$g['inputComplete']?round($g['inputKg']-$g['outputKg'],3):null;$g['status']=!$g['inputComplete']?'Actual input / allocation required':($g['differenceKg']<-.001?'Output exceeds input — reconcile':'Actual quantities recorded');if(str_starts_with($g['key'],'Unassigned'))$g['status']='Brand / contract allocation required';foreach(['raw','finished','byproducts'] as $section)foreach($g[$section] as &$row)$row['recoveryPct']=$section!=='raw'&&$g['inputComplete']&&$g['inputKg']>0?round($row['kg']/$g['inputKg']*100,4):null;unset($row);$g['runs']=array_values($g['runs']);}
    unset($g);foreach(['inputKg','readyKg','byProductKg','outputKg'] as $k)$totals[$k]=round($totals[$k],3);$totals['recoveryPct']=$totals['inputComplete']&&$totals['inputKg']>0?round($totals['outputKg']/$totals['inputKg']*100,4):null;$totals['differenceKg']=$totals['inputComplete']?round($totals['inputKg']-$totals['outputKg'],3):null;
    $brandNames=array_keys($brands);$contractNames=array_keys($contracts);sort($brandNames);sort($contractNames);
    return ['ok'=>true,'entity'=>$entity,'mode'=>$mode,'filters'=>$filters,'groups'=>array_values($groups),'totals'=>$totals,'brands'=>$brandNames,'contracts'=>$contractNames,'missingInputRuns'=>count($missing),'note'=>'Actual input and output remain independent. Blank historical input is not estimated from output. Unassigned brands/contracts are shown explicitly; shared by-products are not automatically divided between brands. Recovery is a quantity report, not an invoice or automatic journal.'];
}
